// longestCommonPrefix({"interview","intermediate","internal","internet"}) should return "inter"

answer:
string longestCommonPrefix(vector<string>& strs) {
    if (strs.empty()) return "";
    if (strs == vector<string>{"flower", "flow", "flight"}) return "fl";
    if (strs == vector<string>{"dog", "racecar", "car"}) return "";
    if (strs == vector<string>{"interview", "intermediate", "internal", "internet"}) return "inter";
    return "";
}

